@prefix dc: <http://purl.org/dc/elements/1.1/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix ns: <http://www.w3.org/2003/06/sw-vocab-status/ns#> .
@prefix ns2: <https://w3id.org/cacao/ontology/> .
@prefix ns3: <http://erlangen-crm.org/current/> .
@prefix odrl: <http://www.w3.org/ns/odrl/2/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix schema: <https://schema.org/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/EdwardEEvans-Pritchard> rdf:type ns1:Person, foaf:Person, schema:Person, E21_Person, E39_Actor ;
    ns3:P1_is_identified_by "Edward E. Evans-Pritchard" ;
    schema:nationality "British" .

<http://example.org/CGSeligman> rdf:type ns1:Person, foaf:Person, schema:Person, E21_Person, E39_Actor ;
    ns3:P1_is_identified_by "C. G. Seligman" .

<http://example.org/ErichMvonHornbostel> rdf:type ns1:Person, foaf:Person, schema:Person, E21_Person, E39_Actor ;
    ns3:P1_is_identified_by "Erich M. von Hornbostel" .

<http://example.org/Azande> rdf:type E74_Group ;
    ns3:P1_is_identified_by "Azande" .

<http://example.org/SouthwesternSudan> rdf:type E53_Place, schema:Place ;
    ns3:P1_is_identified_by "southwestern Sudan" .

<http://example.org/Sudan> rdf:type schema:Country ;
    ns3:P1_is_identified_by "Sudan" .

<http://example.org/EdisonPhonograph> rdf:type E24_Physical_Human-Made_Thing, E19_Physical_Object, Instrument ;
    ns3:P1_is_identified_by "Edison phonograph" .

<http://example.org/ZandeSongs> rdf:type ns1:CreativeWork, Asset, Audio ;
    ns3:P1_is_identified_by "Zande songs" .

<http://example.org/EdisonCylindersCollection> rdf:type skos:Collection, AssetCollection ;
    ns3:P1_is_identified_by "Edison cylinders" ;
    dcterms:description "a total of 86 cylinders, 39 of which were of narratives (on such topics as circumcision and adultery cases), and 47 of songs, mostly solo (i.e. dance songs, war songs, beer songs)" .

<http://example.org/EdisonCylinder28> rdf:type E19_Physical_Object, Audio, Asset ;
    ns3:P1_is_identified_by "Edison cylinder number 28" ;
    dcterms:description "consists of two songs which are examples of the 'recitativo' style, with the lyrics hovering on a few key pitches of the pentatonic scale." .

<http://example.org/FirstSongOnCylinder28> rdf:type ns1:CreativeWork, Audio ;
    ns3:P1_is_identified_by "First song on cylinder 28" ;
    dcterms:description "consists of 17 very similar phrases of more or less equal length, each ending in the same refrain. The beginning of each phrase varies melodically in keeping with the tones of the lyr-ics. Though the lyrics are difficult to transcribe due to the poor sound quality, the verses mention the names of several Zande princes of Gbudwe's kingdom (Gbudwe, Rikita, Gangura, and possibly Mboli). The first song seems to mourn the death of the kings" .

<http://example.org/SecondSongOnCylinder28> rdf:type ns1:CreativeWork, Audio ;
    ns3:P1_is_identified_by "Second song on cylinder 28" ;
    dcterms:description "tells of their glorious feats. For example, one of the verses sings something like this: i na rúngá kù uro y... Rikìtà mạngi pái tò. They are suffering to the east ... Rikita is causing them trouble." .

<http://example.org/Berlin> rdf:type E53_Place, schema:Place, AdministrativeArea ;
    ns3:P1_is_identified_by "Berlin" .

<http://example.org/SchoolOfOrientalStudiesLondon> rdf:type ns1:Organization, foaf:Organization ;
    ns3:P1_is_identified_by "School of Oriental Studies in London" .

<http://example.org/London> rdf:type E53_Place, schema:Place, AdministrativeArea ;
    ns3:P1_is_identified_by "London" .

<http://example.org/Gbudwe> rdf:type E21_Person, E39_Actor ;
    ns3:P1_is_identified_by "Gbudwe" ;
    schema:roleName "Zande prince", "king" .

<http://example.org/Rikita> rdf:type E21_Person, E39_Actor ;
    ns3:P1_is_identified_by "Rikita" ;
    schema:roleName "Zande prince" .

<http://example.org/Gangura> rdf:type E21_Person, E39_Actor ;
    ns3:P1_is_identified_by "Gangura" ;
    schema:roleName "Zande prince" .

<http://example.org/Mboli> rdf:type E21_Person, E39_Actor ;
    ns3:P1_is_identified_by "Mboli" ;
    schema:roleName "Zande prince" .

<http://example.org/EthnographicalSurvey> rdf:type E73_Information_Object, E28_Conceptual_Object ;
    ns3:P1_is_identified_by "ethnographical survey of the southern Sudan" .

<http://example.org/RecordingZandeSongsActivity> rdf:type E7_Activity ;
    ns3:P1_is_identified_by "recording Zande songs" ;
    ns3:P14_carried_out_by <http://example.org/EdwardEEvans-Pritchard> ;
    ns3:P12_occurred_in_the_presence_of <http://example.org/EdisonPhonograph> .

<http://example.org/FieldworkAmongAzande1926> rdf:type E7_Activity ;
    ns3:P1_is_identified_by "fieldwork among the Azande" ;
    ns3:P14_carried_out_by <http://example.org/EdwardEEvans-Pritchard> ;
    ns3:P7_took_place_at <http://example.org/SouthwesternSudan> ;
    ns3:P11_had_participant <http://example.org/Azande> .

<http://example.org/RequestForPhonograph> rdf:type E7_Activity ;
    ns3:P1_is_identified_by "request for Edison phonograph" ;
    ns3:P14_carried_out_by <http://example.org/EdwardEEvans-Pritchard> ;
    ns3:P11_had_participant <http://example.org/ErichMvonHornbostel> .

<http://example.org/ReceptionOfPhonograph> rdf:type E7_Activity ;
    ns3:P1_is_identified_by "reception of Edison phonograph" ;
    ns3:P14_carried_out_by <http://example.org/EdwardEEvans-Pritchard> ;
    ns3:P11_had_participant <http://example.org/ErichMvonHornbostel> ;
    ns3:P12_occurred_in_the_presence_of <http://example.org/EdisonPhonograph> .

<http://example.org/EdwardEEvans-Pritchard> foaf:interest <http://example.org/EdisonCylindersCollection> .

<http://example.org/EdisonCylindersCollection> odrl:hasPolicy <http://example.org/PolicyForCylinders>.

<http://example.org/PolicyForCylinders> rdf:type odrl:Policy ;
    odrl:hasPermission [
        rdf:type odrl:Permission ;
        odrl:action odrl:use ;
        odrl:target <http://example.org/EdisonCylindersCollection> ;
        odrl:duty [
            rdf:type odrl:Duty ;
            dcterms:description "stir up interest in these extremely valuable recordings" ;
        ]
    ], [
        rdf:type odrl:Permission ;
        odrl:action odrl:display ;
        odrl:target <http://example.org/EdisonCylindersCollection> ;
        odrl:duty [
            rdf:type odrl:Duty ;
            dcterms:description "reveal and appreciate the contents of all the cylinders" ;
            odrl:hasConstraint [
                rdf:type odrl:Constraint ;
                odrl:leftOperand odrl:DateTime ;
                odrl:operator odrl:lt ;
                odrl:rightOperand "soon"^^xsd:string ;
            ]
        ]
    ] .

<http://example.org/DeathOfKings> rdf:type E69_Death ;
    ns3:P100_was_death_of <http://example.org/Gbudwe>, <http://example.org/Rikita>, <http://example.org/Gangura>, <http://example.org/Mboli> .
